USE spedmon
GO

IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID('dbo.Patient_Data_Imports_Generate_SpEd_Data_File_Summary_Rows') AND type IN (N'P', N'PC'))
DROP PROCEDURE dbo.Patient_Data_Imports_Generate_SpEd_Data_File_Summary_Rows
GO

/***************************************************************************    
 * Patient_Data_Imports_Generate_SpEd_Data_File_Summary_Rows */    
/**    
 *
 * This routine saves the data generated by the following UDF:
 *   Patient_Data_Imports_Parse_SpEd_Data_File_Into_Summary_Rows_Core
 * 
 * The data is saved in : 
 *   Patient_Data_Imports_SpEd_Data_File_Summary_Rows
 ***************************************************************************/                         

CREATE PROCEDURE [dbo].[Patient_Data_Imports_Generate_SpEd_Data_File_Summary_Rows] (
    @clientID   bigint
  , @minYear    int  = 1988
  , @maxYear    int  = 2100
)
AS

BEGIN

exec dbo.PRINT_STATUS_MESSAGE 'Generating SpEd data file summary rows'

/*###########################################################################*/
/*#  Init and setup                                                         #*/
/*###########################################################################*/

set nocount on

/*###########################################################################*/
/*#  Setup working vars                                                     #*/
/*###########################################################################*/

declare @msg      as varchar(512) = ''
declare @fileID   as bigint       = null
declare @maxIdx   as int          = 0
declare @curIdx   as int          = 0
declare @numRows  as int          = 0
declare @today    as datetime     = getdate()

declare @importFilesThatNeedSavedSummaryRows as table (
    idx    int identity(1,1)
  , fileID bigint 
)

/*###########################################################################*/
/*#  Exit if no client                                                      #*/
/*###########################################################################*/

if (@clientID is null) 
begin
  exec dbo.PRINT_STATUS_MESSAGE 'Client not provided'
  return(0)
end

/*###########################################################################*/
/*#  Get files that need to have summary rows generated                     #*/
/*###########################################################################*/

exec dbo.PRINT_STATUS_MESSAGE 'Searching for files that do not have summary rows generated yet'

insert into @importFilesThatNeedSavedSummaryRows (
  fileID
)
select 
  fileID = a5f.id
from dbo.[Import_From_A.5_SERVICES_From_Client_Files] as a5f
where (
      (a5f.client_id = @clientID)
  and (a5f.canUseData = 1)
  and (a5f.pdiSpEdDataFileSummaryRowsCreated = 0)
)
order by 
  a5f.id asc

set @curIdx = 1
set @maxIdx = 0
select @maxIdx = max(t1.idx) from @importFilesThatNeedSavedSummaryRows as t1

if (@maxIdx > 0) 
begin
  exec dbo.PRINT_STATUS_MESSAGE 'There are file(s) that require summary row generation'
end
else
begin
  exec dbo.PRINT_STATUS_MESSAGE 'There are no file(s) that require summary row generation'
  return(0)
end

while (@curIdx <= @maxIdx)
begin

  set @msg = 'Generating summary rows for ' + convert(varchar(50),@curIdx) + ' of ' + convert(varchar(50),@maxIdx) + ' file(s)'
  exec dbo.PRINT_STATUS_MESSAGE @msg

  select top 1 
      @fileID  = t1.fileID 
    , @numRows = 0
    , @today   = getdate()
  from @importFilesThatNeedSavedSummaryRows as t1 
  where 
    (t1.idx = @curIdx)
    
  insert into dbo.Patient_Data_Imports_SpEd_Data_File_Summary_Rows
  (
      clientID
    , fileID  
    , patID   
    , spEdSvcCode
    , startDate  
    , endDate    
    , spEdFreqCode 
    , svcIdx  
    , totalDuration
    , numSvcLines 
    , svcLinesDetailsJSON
    , dnrFlags 
    , indSvcFlags
    , grpSvcFlags 
    , allDnrFlagsAreTrue 
    , skipSvcContractIfAllDnrFlagsAreTrue
    , individualSvc
    , groupSvc  
    , canUseSvc 
    , latestFileRowID
    , hasEndDate 
    , generatedOn
  )
  select 
      clientID
    , fileID  
    , patID   
    , spEdSvcCode
    , startDate  
    , endDate    
    , spEdFreqCode 
    , svcIdx  
    , totalDuration
    , numSvcLines 
    , svcLinesDetailsJSON
    , dnrFlags 
    , indSvcFlags
    , grpSvcFlags 
    , allDnrFlagsAreTrue 
    , skipSvcContractIfAllDnrFlagsAreTrue
    , individualSvc
    , groupSvc  
    , canUseSvc 
    , latestFileRowID
    , hasEndDate 
	, generatedOn = @today
  from dbo.Patient_Data_Imports_Parse_SpEd_Data_File_Into_Summary_Rows_Core (
      @clientID 
    , null
    , null
    , null
    , @fileID
    , 1 /* Can use row */
    , 1 /* Can use svc */
    , @minYear
    , @maxYear) as t1
  
  set @numRows = @@rowcount
  set @today   = getdate()

  update dbo.[Import_From_A.5_SERVICES_From_Client_Files]
  set 
      pdiSpEdDataFileSummaryRowsCreated = 1
	, pdiSpEdDataFileSummaryRowsCreatedOn = @today
    , pdiSpEdDataFileSummaryRowsCount     = @numRows
  where 
    (id = @fileID)

  set @msg = 'Generated ' + convert(varchar(450),@numRows) + ' rows'
  exec dbo.PRINT_STATUS_MESSAGE @msg

  set @curIdx = @curIdx + 1

end

return(0)

END
GO

GRANT EXECUTE ON  [dbo].[Patient_Data_Imports_Generate_SpEd_Data_File_Summary_Rows] TO [webuser]
GO
